/**
 * More antidote and algorithm questions. Same shape as the ones in skills.ts. All four options of a question are of
 * one kind and about one length, so the wording never gives the answer away. An id, once used, stays: revision and
 * progress are keyed on it.
 */

type W = [string, string][];
/** [id, stem, right answer, why, wrong answers with why not, source] */
export type Row = [string, string, string, string, W, string];

const SNAKE = "National Snakebite Management Protocol (MoHFW, India, 2017); WHO Guidelines for the Management of Snakebites (2016)";

export const MORE_ANTIDOTES: Row[] = [
  ["lead", "A child with abdominal colic, anaemia with basophilic stippling and a blood lead level of 70 µg/dL.", "Chelation with succimer or CaNa₂EDTA", "Chelators bind lead for urinary excretion (add BAL first if encephalopathic); remove the source too.", [["Chelation with desferrioxamine", "For iron."], ["Chelation with penicillamine first", "Second-line; succimer is preferred."], ["Prussian blue by mouth", "For thallium and caesium."]], "CDC lead guidance; TOXBASE"],
  ["arsenic", "Vomiting, rice-water diarrhoea and garlic breath after drinking contaminated water; QT is prolonged.", "Dimercaprol (BAL) or DMSA", "Thiol chelators bind arsenic; supportive care alongside.", [["Desferrioxamine with fluids", "For iron and aluminium."], ["CaNa₂EDTA with fluids", "Used for lead; it isn't effective for arsenic."], ["Prussian blue by mouth", "For thallium and caesium."]], "TOXBASE; WHO arsenic fact sheet"],
  ["mercury", "Tremor, gingivitis and erethism in a worker exposed to mercury vapour.", "DMSA (succimer) or DMPS", "Chelation removes inorganic and elemental mercury.", [["CaNa₂EDTA infusion", "Not effective for mercury."], ["Desferrioxamine infusion", "For iron and aluminium."], ["Prussian blue by mouth", "For thallium and caesium."]], "TOXBASE"],
  ["co", "A family found drowsy in a closed room with a coal heater; headache, vomiting, SpO₂ reads 99%.", "100% oxygen by non-rebreather mask", "Oxygen shortens the half-life of carboxyhaemoglobin (hyperbaric if severe); the pulse oximeter is falsely normal.", [["Oxygen titrated to SpO₂ 94–98%", "The oximeter reads carboxyhaemoglobin as oxygenated, so titrating to it under-treats."], ["IV hydroxocobalamin with room air", "For cyanide; carbon monoxide needs high-flow oxygen."], ["IV methylene blue with room air", "For methaemoglobinaemia; carbon monoxide needs high-flow oxygen."]], "TOXBASE; Undersea and Hyperbaric Medical Society"],
  ["methb", "Cyanosis that doesn't improve with oxygen and chocolate-brown blood after dapsone; methaemoglobin 35%.", "IV methylene blue 1–2 mg/kg", "Reduces methaemoglobin to haemoglobin via NADPH-methaemoglobin reductase (avoid in G6PD deficiency).", [["IV hydroxocobalamin 5 g", "For cyanide."], ["IV ascorbic acid 1 g", "Too slow at this level; kept for when methylene blue can't be given."], ["High-flow oxygen alone", "Doesn't convert methaemoglobin back; the cyanosis has already failed oxygen."]], "BNF (methylthioninium chloride); TOXBASE"],
  ["ethylene-glycol", "After drinking antifreeze: high anion-gap acidosis, an osmolar gap and calcium oxalate crystals in the urine.", "Fomepizole (or ethanol) with haemodialysis", "Blocks alcohol dehydrogenase so glycolate and oxalate aren't formed.", [["Calcium gluconate with urine alkalinisation", "Calcium only for symptomatic hypocalcaemia; neither blocks the toxic metabolites."], ["Thiamine with pyridoxine alone", "Useful cofactors, but they don't stop glycolate and oxalate forming."], ["N-acetylcysteine with haemodialysis", "NAC is for paracetamol; a blocker of alcohol dehydrogenase is needed."]], "EXTRIP; TOXBASE"],
  ["anticholinergic", "Hot, dry, flushed skin, big pupils, urinary retention and agitated delirium after datura seeds.", "Benzodiazepines; physostigmine if severe", "Supportive care first; physostigmine reverses central anticholinergic toxicity, but avoid it if a TCA is suspected.", [["Atropine, titrated to dry secretions", "Another anticholinergic: it makes this worse."], ["Haloperidol for the delirium", "Lowers the seizure threshold, adds to the anticholinergic load and impairs cooling."], ["Flumazenil for the agitation", "Reverses benzodiazepines, which aren't the cause; can provoke seizures."]], "TOXBASE"],
  ["salicylate", "Tinnitus, vomiting and rapid breathing after aspirin overdose; mixed respiratory alkalosis and metabolic acidosis.", "Urine alkalinisation with bicarbonate", "Alkaline urine traps salicylate and speeds its excretion (haemodialysis if severe).", [["IV N-acetylcysteine infusion", "For paracetamol."], ["Forced diuresis with furosemide", "Abandoned: it adds little and causes pulmonary oedema and salt upset."], ["Intubation with deliberate hypoventilation", "Hypoventilation worsens acidosis and can be fatal."]], "TOXBASE; EXTRIP salicylates"],
  ["lithium", "Coarse tremor, confusion and ataxia in a patient on lithium with a level of 4.2 mmol/L and poor kidney function.", "IV fluids and haemodialysis", "Lithium is dialysable; charcoal doesn't bind it.", [["Repeated activated charcoal", "Doesn't bind lithium."], ["Furosemide forced diuresis", "Diuresis and salt loss make the kidney hold on to lithium."], ["Fluid restriction and a thiazide", "Both raise the lithium level."]], "EXTRIP lithium"],
  ["paraquat", "A farmer swallowed weedkiller; burning mouth ulcers and later breathlessness.", "Supportive care; oxygen if hypoxic", "There's no specific antidote; oxygen increases paraquat's free-radical lung damage.", [["100% oxygen by non-rebreather mask", "Worsens the lung injury."], ["Atropine and pralidoxime", "Paraquat is not an organophosphate."], ["Urine alkalinisation with bicarbonate", "For salicylates; it doesn't clear paraquat."]], "TOXBASE; WHO"],
  ["aluminium-phosphide", "After swallowing a 'celphos' tablet: profound shock, a garlic smell and refractory acidosis.", "Supportive care; no specific antidote", "Phosphine gas causes myocardial toxicity; magnesium and supportive care are used, and water lavage is avoided.", [["Atropine and pralidoxime", "Not an organophosphate."], ["Hydroxocobalamin and oxygen", "For cyanide."], ["Water lavage followed by activated charcoal", "Water releases more phosphine gas, and charcoal isn't an antidote."]], "AIIMS Poison Control; TOXBASE"],
  ["scorpion", "A child stung by a red scorpion has cold extremities, sweating, priapism and BP 170/110.", "Oral prazosin, repeated by response", "Prazosin blocks the alpha-adrenergic storm of Mesobuthus tamulus envenoming (add scorpion antivenom if available).", [["Sublingual nifedipine, repeated", "Unpredictable BP falls; it isn't recommended."], ["IV atropine, repeated", "Worsens the adrenergic storm."], ["IV hydrocortisone with antihistamine", "Not effective for the venom."]], "Indian Academy of Pediatrics; Bawaskar"],
  ["krait", "A snakebite at night with no local signs; ptosis and difficulty swallowing next morning.", "Polyvalent ASV with ventilatory support", "Neurotoxic envenoming needs ASV and ventilation if weak. Krait toxin acts presynaptically, so a neostigmine–atropine trial, which helps cobra's postsynaptic block, usually does little.", [["Neostigmine–atropine trial alone, with no ASV", "Krait toxin is presynaptic; neostigmine helps mainly cobra, and never replaces ASV."], ["ASV only once clotting is abnormal", "Krait doesn't cause coagulopathy; neuroparalysis is itself an ASV indication."], ["Vitamin K with fresh frozen plasma", "For bleeding disorders; this bite doesn't cause one."]], SNAKE],
  ["valproate", "A large valproate overdose with coma and a high ammonia.", "IV L-carnitine", "Carnitine replenishes stores depleted by valproate and reduces hyperammonaemia.", [["IV pyridoxine", "For isoniazid."], ["IV thiamine", "For Wernicke's."], ["IV flumazenil", "For benzodiazepines."]], "TOXBASE"],
  ["insulin", "A patient injected 300 units of insulin; glucose is 32 mg/dL.", "IV dextrose bolus, then infusion", "Insulin overdose needs prolonged glucose support and frequent checks; add potassium as needed.", [["Octreotide with oral sugar", "For sulfonylureas; here the insulin is already injected."], ["IM glucagon, repeated alone", "Short-acting; not enough for a large depot of insulin."], ["Oral sugar, await symptoms", "Treat low glucose at once, by vein at this level."]], "TOXBASE"],
  ["rivaroxaban", "A patient on apixaban has a life-threatening intracranial bleed.", "Andexanet alfa (or 4-factor PCC)", "Andexanet binds factor Xa inhibitors; PCC is used where it isn't available.", [["Idarucizumab (or vitamin K)", "For dabigatran (and warfarin)."], ["Protamine (or vitamin K)", "For heparin (and warfarin)."], ["Tranexamic acid (or plasma)", "Neither reverses a factor Xa inhibitor."]], "BNF; ESC/EHRA practical guide on DOACs"],
  ["serotonin", "After starting tramadol in a patient on an SSRI: clonus, hyperthermia, agitation and diarrhoea.", "Stop drugs; diazepam and cyproheptadine", "Cyproheptadine is a 5-HT2A antagonist used for moderate serotonin syndrome; cool as needed.", [["Stop drugs; cooling and dantrolene", "Dantrolene is for malignant hyperthermia; clonus points to serotonin."], ["Stop drugs; cooling and oral bromocriptine", "For NMS; it worsens serotonin syndrome."], ["Stop drugs; cooling and haloperidol", "May worsen it, and it can bring on NMS."]], "Hunter criteria; TOXBASE"],
  ["nms", "Rigidity, high fever, confusion and a CK of 18,000 after starting haloperidol.", "Stop the drug, cool, then bromocriptine", "Dopamine blockade causes NMS; a dopamine agonist reverses it, with dantrolene for severe rigidity.", [["Stop the drug, cool, then cyproheptadine", "For serotonin syndrome."], ["Stop the drug, cool, then physostigmine", "For anticholinergic toxicity."], ["Stop the drug, cool, then olanzapine", "Another dopamine blocker keeps the cause going."]], "TOXBASE"],
  ["mh", "During anaesthesia with sevoflurane and suxamethonium: rising end-tidal CO₂, rigidity and fever.", "Stop volatile; IV dantrolene", "Dantrolene blocks calcium release from the sarcoplasmic reticulum.", [["Stop volatile; oral bromocriptine", "For NMS."], ["Stop volatile; IV paracetamol", "Doesn't treat the muscle hypermetabolism of MH."], ["Stop volatile; IV lipid emulsion", "For local anaesthetic toxicity."]], "Association of Anaesthetists MH guideline"],
  ["mushroom", "Severe vomiting and diarrhoea 10 hours after eating wild mushrooms, then rising transaminases.", "Silibinin, NAC and transplant referral", "Amatoxin causes delayed liver failure; silibinin (or high-dose penicillin) blocks its uptake.", [["Atropine, fluids and observation", "For muscarinic mushrooms, which act within hours and don't harm the liver."], ["Pyridoxine, fluids and observation", "For gyromitrin mushrooms, whose main feature is seizures."], ["Charcoal, fluids and discharge", "Rising transaminases at this delay mean amatoxin: she can't go home."]], "TOXBASE"],
  ["botulism", "Descending paralysis with fixed dilated pupils after home-canned food.", "Botulinum antitoxin with ventilation", "Antitoxin neutralises circulating toxin; it doesn't reverse established paralysis.", [["Neostigmine with ventilation", "Not effective in botulism."], ["IV immunoglobulin with ventilation", "For Guillain–Barré and myasthenia; it doesn't neutralise toxin as antitoxin does."], ["Polyvalent ASV with ventilation", "For snakebite."]], "CDC botulism guidance"],
  ["oral-hypo-metformin", "Severe lactic acidosis (pH 6.9) after a metformin overdose.", "Haemodialysis with supportive care", "Metformin is dialysable; dialysis corrects the acidosis.", [["Octreotide with supportive care", "For sulfonylurea hypoglycaemia."], ["Glucagon with supportive care", "Doesn't remove metformin or correct the acidosis."], ["Insulin–dextrose with supportive care", "Not indicated: it neither removes metformin nor corrects the acidosis."]], "EXTRIP metformin"],
  ["theophylline", "Seizures, vomiting and tachyarrhythmia with a theophylline level of 60 mg/L.", "Repeated charcoal, with haemodialysis", "Theophylline is removed by multiple-dose charcoal and, if severe, dialysis.", [["IV phenytoin for the seizures", "Ineffective in theophylline seizures; benzodiazepines are used."], ["Urine alkalinisation with bicarbonate", "For salicylates; it doesn't clear theophylline."], ["Forced diuresis with furosemide", "Doesn't clear theophylline and worsens the low potassium."]], "EXTRIP theophylline"],
  ["kerosene", "A toddler swallowed kerosene and is coughing.", "Supportive care, watching for aspiration", "The danger is aspiration pneumonitis; no emesis and no lavage.", [["Induced vomiting, then observation", "Causes aspiration."], ["Gastric lavage, then observation", "Raises the risk of aspiration."], ["Activated charcoal, then observation", "Doesn't bind hydrocarbons, and vomiting risks aspiration."]], "IAP; TOXBASE"],
  ["corrosive", "A woman drank toilet cleaner (acid) an hour ago and has drooling and chest pain.", "Nil by mouth, then early endoscopy", "Assess the airway first. Neutralising or inducing vomiting causes more injury.", [["Milk to neutralise, then endoscopy", "Adds heat and blurs the view, and more injury follows."], ["Induced vomiting, then endoscopy", "Re-exposes the oesophagus."], ["Activated charcoal, then endoscopy", "Doesn't bind corrosives and obscures endoscopy."]], "TOXBASE"],
  ["clonidine", "A toddler with bradycardia, small pupils and drowsiness after swallowing a grandparent's clonidine.", "Supportive care; naloxone may help", "Clonidine mimics opioid toxicity; naloxone in high doses sometimes helps, with atropine for bradycardia.", [["Flumazenil with supportive care", "For benzodiazepines."], ["Physostigmine with supportive care", "For anticholinergic toxicity, the opposite picture."], ["Prazosin with supportive care", "An alpha-blocker: it would drop the BP further."]], "TOXBASE"],
  ["dapsone-hb", "A patient on primaquine has dark urine and falling haemoglobin; G6PD is deficient.", "Stop the drug; transfuse if needed", "Oxidant drugs cause haemolysis in G6PD deficiency; methylene blue is avoided.", [["IV methylene blue; transfuse if needed", "Ineffective and harmful in G6PD deficiency."], ["IV steroids; transfuse if needed", "Not effective: this isn't immune haemolysis."], ["Folinic acid; continue the drug", "The oxidant drug must stop."]], "WHO malaria guidelines"],
  ["heparin-hit", "Platelets fall by 60% on day 7 of heparin, with a new DVT.", "Stop heparin; start argatroban", "HIT is prothrombotic and needs a non-heparin anticoagulant (argatroban or fondaparinux); protamine and platelet transfusion don't treat it.", [["Stop heparin; switch to enoxaparin", "LMWH cross-reacts with the HIT antibodies."], ["Stop heparin; transfuse platelets", "May worsen thrombosis, and the DVT goes untreated."], ["Stop heparin; give IV protamine", "Doesn't treat HIT, and the DVT goes untreated."]], "ASH HIT guideline 2018"],
  ["local-methemoglobin", "Cyanosis after a large dose of topical benzocaine spray before endoscopy.", "IV methylene blue", "Benzocaine causes methaemoglobinaemia.", [["IV naloxone", "For opioids."], ["IV 20% lipid emulsion", "For systemic local anaesthetic cardiotoxicity, not methaemoglobinaemia."], ["IV hydroxocobalamin", "For cyanide."]], "TOXBASE"],
  ["ethanol", "A comatose drinker with glucose 45 mg/dL and nystagmus.", "IV thiamine with glucose", "Give thiamine with glucose in malnourished drinkers to prevent Wernicke's.", [["IV flumazenil with glucose", "Not for alcohol, and it can cause seizures."], ["IV naloxone with glucose", "Not for alcohol."], ["IV fomepizole with glucose", "For methanol/ethylene glycol."]], "NICE alcohol-use disorders; RCP"],
  ["cyanide-nitroprusside", "Rising lactate and metabolic acidosis during a long high-dose sodium nitroprusside infusion.", "Stop it; give hydroxocobalamin", "Nitroprusside releases cyanide; sodium thiosulfate can be added.", [["Stop it; give methylene blue", "For methaemoglobinaemia."], ["Stop it; give calcium gluconate", "For calcium-channel blockers and high potassium."], ["Stop it; give lipid emulsion", "For local anaesthetic toxicity."]], "BNF (sodium nitroprusside)"],

  /* Bites, stings and envenomations */
  ["russell-viper", "A farmer bitten on the ankle brings the dead snake: a Russell's viper. Swelling, gum bleeding, scanty urine, and the 20-minute clotting test stays liquid.", "Polyvalent ASV; recheck in 6 hours", "Haemotoxic envenoming: ASV neutralises the venom and clotting returns over about 6 hours, so repeat the 20WBCT 6-hourly; watch for kidney injury and dialyse if needed.", [["FFP and vitamin K; recheck in 6 hours", "They don't neutralise venom, so the factors keep being consumed."], ["Low-dose heparin; recheck in 6 hours", "Heparin doesn't help venom coagulopathy and adds to the bleeding."], ["Tranexamic acid; recheck in 6 hours", "Doesn't neutralise venom or restore clotting."]], SNAKE],
  ["asv-repeat", "Six hours after the first ASV dose for a viper bite, the 20-minute clotting test is still liquid.", "Repeat ASV; recheck 20WBCT in 6 hours", "Persisting coagulopathy means venom is still active: repeat ASV and retest 6-hourly until blood clots.", [["Give FFP alone; stop further ASV", "Without ASV, venom keeps consuming the new factors."], ["Start heparin; stop further ASV", "Heparin isn't useful in venom coagulopathy and raises bleeding risk."], ["Wait 24 hours; then recheck clotting", "Unneutralised venom keeps her at risk of bleeding."]], SNAKE],
  ["cobra", "A man clearing a woodpile sees a cobra strike. Within an hour: a painful blistering swelling at the bite, ptosis and slurred speech.", "Polyvalent ASV with neostigmine–atropine", "Cobra toxin acts postsynaptically, so an anticholinesterase can help; give atropine first, and ventilate if needed.", [["Polyvalent ASV with fresh frozen plasma", "Plasma is for coagulopathy; it does nothing for neuromuscular block."], ["Neostigmine–atropine trial, holding back ASV", "Neuroparalysis is an ASV indication; neostigmine is only an adjunct."], ["Polyvalent ASV with IV immunoglobulin", "Immunoglobulin is for Guillain–Barré and myasthenia, not envenoming."]], SNAKE],
  ["asv-reaction", "During an ASV infusion: urticaria, wheeze and BP 80/50.", "Stop infusion; IM adrenaline 0.5 mg", "Treat as anaphylaxis, then restart ASV slowly once settled: the bite still needs treating.", [["Slow infusion; IV chlorphenamine alone", "Too little for anaphylaxis with hypotension."], ["Stop ASV for good; IV hydrocortisone alone", "Steroids are slow, and the envenoming still needs ASV."], ["Stop infusion; IV adrenaline 1 mg bolus", "The arrest dose: dangerous in a patient with a pulse."]], SNAKE],
  ["bee-sting", "Minutes after a bee sting on the neck: generalised hives, wheeze, faintness and BP 78/40.", "IM adrenaline 0.5 mg, outer thigh", "Anaphylaxis from a sting is treated as any other; scrape off the stinger at once.", [["IV chlorphenamine 10 mg, slowly", "Treats only the skin; doesn't save life."], ["IV hydrocortisone 200 mg, slowly", "Too slow, and not first line."], ["Nebulised salbutamol 5 mg, first", "Adds to, but never replaces, IM adrenaline."]], "Resuscitation Council UK 2021; WAO"],
  ["rabies-cat3", "A stray dog bit through the skin of a child's cheek an hour ago and the wound bled.", "Wash; Ig into wound, plus vaccine", "A transdermal bite (as is any bat exposure) is category III: wash for 15 minutes, infiltrate immunoglobulin into and around the wound, and start the vaccine.", [["Wash; vaccine course alone, no Ig", "Category III needs immunoglobulin too; vaccine alone takes days to protect."], ["Wash; Ig into wound, with no vaccine", "Immunoglobulin protects only for a time; the vaccine must follow."], ["Suture; vaccine only if the dog dies", "Don't wait on the dog, and avoid primary suture before immunoglobulin."]], "National Guidelines for Rabies Prophylaxis (NCDC, India, 2019); WHO rabies position paper (2018)"],
  ["centipede", "A gardener has burning pain and swelling at a centipede bite on the foot, with no systemic features.", "Local care, analgesia, tetanus check", "Centipede bites are usually only locally painful; there's no antivenom.", [["Polyvalent ASV, analgesia, tetanus check", "Snake antivenom has no role."], ["Oral prazosin, analgesia, tetanus check", "For the adrenergic storm of red scorpion stings."], ["Tourniquet, analgesia, tetanus check", "Harmful, and it does nothing for the pain."]], "Auerbach's Wilderness Medicine"],
  ["jellyfish", "A swimmer on a tropical beach has box-jellyfish tentacles stuck to the leg, with severe pain.", "Vinegar for 30 seconds, then lift tentacles off", "Vinegar stops undischarged stinging cells from firing; then remove tentacles and treat pain. Antivenom if collapse.", [["Fresh water for 30 seconds, then rub tentacles off", "Fresh water and rubbing fire more stinging cells."], ["Urine for 30 seconds, then scrape tentacles off", "A myth: it can fire more stinging cells."], ["Alcohol for 30 seconds, then rub tentacles off", "Alcohol can fire more stinging cells."]], "ANZCOR guideline on jellyfish stings"],
  ["stingray", "A fisherman trod on a stingray and has a barb wound in the heel with excruciating pain.", "Hot-water immersion; explore the wound", "The venom is heat-labile: soak in hot water (about 45°C), then remove the fragments and check for a retained barb.", [["Ice-pack compression; explore the wound", "Cold doesn't ease this pain, and heat is what inactivates the venom."], ["Polyvalent ASV; primary wound closure", "Snake antivenom has no role, and closing the wound traps fragments and infection."], ["Pressure bandage; primary wound closure", "Doesn't help this venom, and closing the wound traps fragments and infection."]], "Auerbach's Wilderness Medicine"],
  ["snake-firstaid", "A relative phones: his father was bitten on the calf by a snake 20 minutes ago, and the hospital is an hour away.", "Immobilise the limb; transport urgently", "Keep the patient still with the limb splinted, remove rings and tight items, and get to hospital.", [["Tie a tourniquet; transport urgently", "Causes ischaemia and a surge of venom on release."], ["Cut and suck the bite; transport urgently", "Adds bleeding and infection and removes no useful venom."], ["Ice the bite; walk to the main road", "Ice damages tissue, and walking spreads the venom."]], SNAKE],
  ["tick", "A 4-year-old has ascending flaccid paralysis and absent reflexes; an engorged tick is found on the scalp.", "Remove the tick; supportive care", "Tick paralysis comes from a salivary neurotoxin and usually clears within days once the tick is out; check the airway.", [["Leave the tick; IV immunoglobulin", "For Guillain–Barré: the tick must be removed, or she worsens."], ["Leave the tick; plasma exchange", "For Guillain–Barré: the tick must be removed, or she worsens."], ["Leave the tick; oral doxycycline", "For tick-borne infections; this is a toxin, and the tick must come out."]], "Harrison's Principles of Internal Medicine"],
  ["spider", "A man bitten by a black widow spider has severe muscle cramps, a board-like abdomen, sweating and raised BP.", "Opioid analgesia with a benzodiazepine", "Latrodectism is treated mainly for pain and spasm; specific antivenom, where available, is for severe cases.", [["IV calcium gluconate with fluids", "Once popular; it doesn't relieve the cramps."], ["Neostigmine with atropine cover", "For cobra neurotoxicity; widow venom releases too much neurotransmitter."], ["Surgical excision of the bite site", "Doesn't remove venom and adds a wound."]], "Auerbach's Wilderness Medicine; TOXBASE"],

  /* Anaesthesia, perioperative and ICU reversal */
  ["rocuronium", "Rocuronium was given at induction; intubation has failed and the team wants the block gone immediately.", "Sugammadex 16 mg/kg IV", "It encapsulates rocuronium: 16 mg/kg reverses even a profound block within minutes.", [["Sugammadex 2 mg/kg IV", "The dose for a shallow block at the end of surgery; too little here."], ["Neostigmine 0.05 mg/kg IV", "Can't reverse a profound block."], ["Flumazenil 0.5 mg IV", "Reverses benzodiazepines, not paralysis."]], "BNF (sugammadex); Miller's Anesthesia"],
  ["atracurium", "At the end of surgery after atracurium, the train-of-four shows 2 twitches and the patient is weak.", "Neostigmine with glycopyrrolate", "An anticholinesterase reverses a benzylisoquinoline once twitches return; the anticholinergic blocks the bradycardia.", [["Sugammadex with glycopyrrolate", "Binds only steroidal relaxants (rocuronium, vecuronium), not atracurium."], ["Neostigmine with no anticholinergic", "Risks bradycardia, bronchospasm and secretions."], ["Flumazenil with glycopyrrolate", "Reverses benzodiazepines, not paralysis."]], "BNF; Miller's Anesthesia"],
  ["sux-apnoea", "No twitches 40 minutes after suxamethonium for a 5-minute procedure; a relative had the same problem.", "Ventilate and sedate until it clears", "Pseudocholinesterase deficiency: the block wears off in hours; keep the patient unaware, then test the family.", [["Give FFP to replace the cholinesterase", "Not routine: the block wears off by itself, and plasma carries its own risks."], ["Neostigmine to reverse the block", "Unpredictable: it can deepen a suxamethonium block."], ["Sugammadex to reverse the block", "Binds rocuronium and vecuronium only."]], "Miller's Anesthesia; Association of Anaesthetists"],
  ["pris", "On high-dose propofol for 4 days in ICU: new metabolic acidosis, rising CK, lipaemia and bradycardia.", "Stop propofol; supportive care", "Propofol infusion syndrome has no antidote: stop the drug, change the sedative, support the circulation, and dialyse if needed.", [["Stop propofol; IV dantrolene", "For malignant hyperthermia; it isn't a treatment here."], ["Stop propofol; IV lipid emulsion", "Adds fat to a failing fat metabolism."], ["Halve propofol; IV bicarbonate", "Any propofol keeps the syndrome going; it must stop."]], "Kam & Cardone, Anaesthesia 2007; Miller's Anesthesia"],
  ["postop-opioid", "Two hours after surgery on a morphine PCA: RR 6/min, drowsy, pinpoint pupils, SpO₂ 88%.", "IV naloxone in small titrated doses", "Give oxygen and titrate to breathing, not full wakefulness; watch for re-sedation, since naloxone wears off first.", [["IV naloxone 2 mg as a single bolus", "Brings severe pain, hypertension and pulmonary oedema in a post-op patient."], ["IV flumazenil in small titrated doses", "Reverses benzodiazepines, not opioids."], ["IV doxapram by continuous infusion", "A non-specific stimulant; it doesn't reverse the opioid."]], "BNF (naloxone); Resuscitation Council UK"],
  ["dexmedetomidine", "On a dexmedetomidine infusion after cardiac surgery: HR 38 and BP 80/50.", "Stop the infusion; give IV atropine", "There's no specific antidote: stop the alpha-2 agonist and treat the bradycardia with an anticholinergic.", [["Stop the infusion; give IV flumazenil", "Dexmedetomidine isn't a benzodiazepine."], ["Stop the infusion; give IV naloxone", "Dexmedetomidine isn't an opioid."], ["Keep the infusion; give IV adenosine", "Adenosine slows conduction further."]], "BNF (dexmedetomidine); Miller's Anesthesia"],
  ["icu-nms", "Five days after haloperidol for ICU delirium, with no recent anaesthetic: lead-pipe rigidity, 40.5°C, swinging BP and CK 20,000.", "Stop it, cool, give dantrolene", "NMS: with no volatile agent this isn't MH, and rigidity without clonus isn't serotonin syndrome. Dantrolene eases severe rigidity; bromocriptine is the other option.", [["Stop it, cool, give oral cyproheptadine", "For serotonin syndrome."], ["Stop it, cool, give IV physostigmine", "For anticholinergic toxicity."], ["Stop it, cool, change to olanzapine", "Another dopamine blocker keeps the cause going."]], "TOXBASE; Miller's Anesthesia"],
  ["methb-g6pd", "Cyanosis and brown blood after prilocaine; methaemoglobin 40%, with known G6PD deficiency.", "IV ascorbic acid; exchange transfusion", "Methylene blue needs NADPH, which G6PD-deficient cells can't make: it fails and causes haemolysis. Use ascorbic acid, with exchange transfusion if severe.", [["IV methylene blue 1–2 mg/kg, repeated", "Contraindicated: it causes haemolysis in G6PD deficiency."], ["IV methylene blue, half the usual dose", "Still risks haemolysis, and it won't work without NADPH."], ["IV hydroxocobalamin, then observe", "For cyanide."]], "BNF (methylthioninium chloride); TOXBASE"],
  ["sux-hyperk", "Suxamethonium given to a patient with 10-day-old burns; peaked T waves, a wide QRS and VT within minutes.", "IV calcium, then insulin–dextrose", "Burns upregulate receptors, so suxamethonium releases a surge of potassium: protect the heart first, then shift it.", [["IV dantrolene, then active cooling", "For malignant hyperthermia; the ECG here is hyperkalaemic."], ["IV lidocaine, then amiodarone", "Don't treat the potassium: the VT will recur."], ["IV neostigmine, then atropine", "Reverses non-depolarising block, and it prolongs suxamethonium."]], "Miller's Anesthesia; UK Kidney Association hyperkalaemia guideline"],

  /* Heart and blood */
  ["lysis-bleed", "New intracranial bleed an hour after alteplase for stroke; fibrinogen is 90 mg/dL.", "Cryoprecipitate with tranexamic acid", "Stop the infusion; cryoprecipitate restores fibrinogen and tranexamic acid blocks fibrinolysis.", [["Protamine with tranexamic acid", "Protamine reverses heparin; low fibrinogen goes uncorrected."], ["Vitamin K with platelet transfusion", "The problem is fibrinolysis, not vitamin K factors."], ["Idarucizumab with fresh frozen plasma", "Idarucizumab reverses dabigatran only."]], "AHA/ASA acute stroke guideline 2019"],
  ["lmwh-protamine", "A major bleed 4 hours after a therapeutic dose of enoxaparin.", "IV protamine; reverses it only partly", "Protamine neutralises anti-IIa fully but anti-Xa only in part, about 60%, for LMWH.", [["IV idarucizumab; reverses it fully", "Binds dabigatran only."], ["IV vitamin K; reverses it within hours", "Enoxaparin doesn't act through vitamin K."], ["Plasma alone; reverses it fully", "Plasma doesn't neutralise enoxaparin."]], "BNF (protamine sulfate)"],
  ["drug-torsades", "Polymorphic VT with a long QT after haloperidol and ondansetron; a pulse is present and BP is 110/70.", "IV magnesium sulfate 2 g", "Magnesium stabilises the membrane even when serum magnesium is normal; correct potassium, and shock if pulseless.", [["IV amiodarone 300 mg over 1 hour", "Prolongs QT further."], ["IV sotalol 100 mg", "Prolongs QT further."], ["IV adenosine 6 mg", "Doesn't treat a ventricular rhythm."]], "AHA ACLS 2020"],

  /* Metabolic */
  ["tumour-lysis", "After chemotherapy for Burkitt's lymphoma: urate 15 mg/dL, K 6.0, high phosphate, rising creatinine. G6PD is normal.", "IV fluids with rasburicase", "Rasburicase breaks down existing urate fast. It's contraindicated in G6PD deficiency (haemolysis, methaemoglobinaemia), so check first.", [["IV fluids with allopurinol", "Only stops new urate forming; established lysis needs urate cleared."], ["IV fluids with bicarbonate", "No longer advised: alkaline urine precipitates calcium phosphate."], ["IV fluids with probenecid", "Drives more urate into the urine and failing tubules."]], "British Society for Haematology tumour lysis guideline; Cairo–Bishop definition"],
  ["hyperammonaemia", "A cirrhotic is drowsy with asterixis after days of constipation; no bleeding or infection is found.", "Lactulose with rifaximin", "Lactulose traps ammonia in the gut and clears it; rifaximin cuts ammonia-making bacteria and prevents recurrence.", [["Flumazenil with haloperidol", "Flumazenil helps only briefly, and haloperidol sedates further."], ["Protein restriction with furosemide", "Restriction worsens wasting; a diuretic can precipitate encephalopathy."], ["Neostigmine with prucalopride", "Neither lowers ammonia."]], "AASLD/EASL hepatic encephalopathy guideline 2014"],
  ["hypercalcaemia", "Breast cancer with confusion, dry mucosae and normal kidneys; corrected calcium 15 mg/dL.", "IV saline, calcitonin and zoledronate", "Saline restores volume, calcitonin acts in hours, and the bisphosphonate lasts for weeks.", [["IV saline, thiazide and zoledronate", "Thiazides raise calcium."], ["IV saline, calcitriol and zoledronate", "Calcitriol raises calcium."], ["Furosemide, calcitonin and zoledronate", "A loop diuretic in a dry patient worsens volume depletion; rehydrate first."]], "Endocrine Society hypercalcaemia of malignancy guideline 2023"],
  ["porphyria", "A young woman has severe abdominal pain, confusion, low sodium and dark urine soon after starting a barbiturate.", "IV haem arginate; stop the drug", "An acute porphyria attack: haem shuts down the pathway; add glucose, and use safe analgesia and drugs.", [["IV desferrioxamine; stop the drug", "For iron overload."], ["IV folinic acid; stop the drug", "For methotrexate."], ["IV phenytoin; stop the drug", "Itself a porphyria trigger."]], "Harrison's Principles of Internal Medicine; British and Irish Porphyria Network"],
  ["wilson", "A 19-year-old with tremor, Kayser–Fleischer rings, cirrhosis, low caeruloplasmin and high urinary copper.", "D-penicillamine or trientine", "Copper chelators treat symptomatic Wilson's disease; zinc is for maintenance.", [["Desferrioxamine or deferasirox", "Iron chelators."], ["CaNa₂EDTA or succimer", "For lead; these aren't the treatment for copper."], ["Prussian blue or charcoal", "For thallium, caesium and ingested toxins."]], "AASLD Wilson disease guidance (2022)"],
  ["refeeding", "A severely malnourished man on day 2 of feeding: weak, confused, oedematous; phosphate 0.9 mg/dL.", "Slow feeds; IV phosphate and thiamine", "Refeeding syndrome: go slower, replace phosphate, potassium and magnesium, and give thiamine.", [["Speed up feeds; insulin to use the glucose", "More carbohydrate and insulin drive phosphate further down."], ["Stop feeds; furosemide for the oedema", "Doesn't replace phosphate; furosemide wastes more salts."], ["Keep feeds; extra dextrose infusion", "More glucose drives phosphate further into cells."]], "NICE nutrition support in adults; ASPEN refeeding consensus 2020"],
  ["hypocalcaemia-thyroid", "A day after total thyroidectomy: perioral tingling, carpopedal spasm, QTc 490 ms and calcium 6.8 mg/dL.", "IV calcium gluconate, slowly", "Symptomatic, severe: IV calcium with monitoring, then oral calcium and vitamin D; check magnesium.", [["Oral calcium carbonate alone", "Too slow with tetany and a long QT."], ["Oral calcitriol alone", "Takes days to work."], ["Paper-bag rebreathing alone", "For hyperventilation; the low calcium here is real."]], "Society for Endocrinology emergency guidance"],

  /* Poisons */
  ["organochlorine", "A farmer swallowed endosulfan: vomiting, then repeated seizures; pupils are normal and there are no secretions.", "Benzodiazepines with supportive care", "Organochlorines block GABA; there's no antidote, and atropine isn't indicated. Avoid adrenaline if possible (arrhythmia).", [["Atropine in doubling doses with pralidoxime", "For organophosphates; this has no cholinergic signs."], ["Phenytoin with supportive care", "Poor for toxin seizures; a benzodiazepine comes first."], ["Flumazenil with supportive care", "Lowers the seizure threshold further."]], "WHO / IPCS Poisons Information; AIIMS Poison Control Centre protocols"],
  ["pyrethroid", "After spraying cypermethrin without a mask: facial tingling and mild tremor; pupils and secretions are normal.", "Wash the skin and supportive care", "Pyrethroids are low in toxicity: decontaminate and treat symptoms. Atropine is only for true cholinergic signs.", [["Atropine in doubling doses until dry", "Risks atropine toxicity with no cholinergic excess to treat."], ["Pralidoxime by continuous infusion", "For organophosphates."], ["Oral cyproheptadine, repeated", "For serotonin syndrome."]], "WHO / IPCS Poisons Information; AIIMS Poison Control Centre protocols"],
  ["oleander", "After eating yellow oleander seeds: vomiting, HR 36 with AV block and potassium 6.2.", "Digoxin-specific Fab fragments", "Oleander's cardiac glycosides cross-react with digoxin Fab, which restores rhythm and corrects the potassium.", [["IV calcium gluconate, repeated", "Traditionally avoided in glycoside toxicity, and it doesn't bind the toxin."], ["Haemodialysis for the potassium", "Doesn't remove the glycoside or reverse the block."], ["Physostigmine by slow bolus", "For anticholinergic toxicity; it slows the heart further."]], "Eddleston et al., Lancet 2000; TOXBASE"],

  /* Painkillers and psychiatric drugs */
  ["dystonia", "Neck twisted and eyes rolled upwards a few hours after IM haloperidol.", "IV procyclidine or benztropine", "Acute dystonia responds within minutes to an anticholinergic; a course may follow for a few days.", [["IV dantrolene or bromocriptine", "For NMS, which has fever and rigidity."], ["IV flumazenil or naloxone", "Reverse benzodiazepines and opioids, not dystonia."], ["Oral propranolol or clonazepam", "For akathisia, and too slow here."]], "BNF (procyclidine)"],
];

export const MORE_ALGORITHMS: Row[] = [
  ["rosc", "After 3 cycles of CPR in VF, the patient has a pulse and BP 90/60, and isn't waking.", "Airway, SpO₂ 94–98%, 12-lead ECG, MAP ≥ 65", "Avoid hypoxia and hypotension, control temperature, and get an ECG to look for a STEMI needing PCI.", [["Airway, 100% oxygen for 24 hours, ECG tomorrow", "Hyperoxia is harmful, and the ECG can't wait."], ["Extubate early, amiodarone infusion, routine ECG", "He isn't waking, and amiodarone isn't routine after ROSC."], ["Transfer to ward, routine observations", "Re-arrest is common: he needs ICU."]], "AHA ACLS 2020; ERC 2021"],
  ["brady-unstable", "HR 32 with BP 75/40 and confusion; complete heart block on the ECG.", "Atropine 1 mg; then pacing or adrenaline", "Unstable bradycardia: atropine first (repeat up to 3 mg), pacing or an infusion if it fails.", [["Adenosine 6 mg; then pacing or adrenaline", "For SVT; it worsens AV block."], ["Amiodarone 300 mg; then pacing", "Slows the heart further."], ["Observe; cardiology review in the morning", "This is unstable."]], "AHA ACLS 2020"],
  ["svt-stable", "Regular narrow-complex tachycardia at 190/min; BP 120/80 and alert.", "Modified Valsalva, then adenosine 6 mg", "Stable SVT: vagal first, rapid IV adenosine next.", [["DC shock, then adenosine 6 mg", "Shock only if unstable."], ["Amiodarone 300 mg, then DC shock", "Not first line for SVT, and she's stable."], ["Digoxin 500 mcg, then review", "Too slow; it doesn't terminate SVT."]], "AHA ACLS 2020; Resus Council UK"],
  ["vt-pulse-unstable", "Broad-complex tachycardia at 180/min with BP 70/40 and chest pain.", "Synchronised DC cardioversion", "Unstable tachycardia with a pulse: synchronised shock.", [["Unsynchronised defibrillation", "For pulseless VT/VF."], ["IV adenosine 6 mg rapidly", "Not for unstable broad-complex tachycardia."], ["IV amiodarone 300 mg slowly", "For stable VT; instability needs a shock first."]], "AHA ACLS 2020"],
  ["vt-pulse-stable", "Monomorphic broad-complex tachycardia at 160/min, BP 125/80, no chest pain.", "IV amiodarone 300 mg slowly", "Stable VT: antiarrhythmic over 20–60 minutes with expert help; be ready to cardiovert.", [["IV verapamil 5 mg slowly", "Can cause collapse in VT."], ["Unsynchronised defibrillation", "For pulseless rhythms."], ["Oral bisoprolol, then discharge", "Needs treatment now."]], "AHA ACLS 2020; Resus Council UK"],
  ["af-fast-unstable", "New AF at 170/min with BP 75/50 and pulmonary oedema.", "Synchronised DC cardioversion", "Haemodynamically unstable AF: electrical cardioversion now.", [["IV adenosine 6 mg rapidly", "Doesn't convert AF."], ["Oral digoxin, 500 mcg load", "Too slow."], ["Anticoagulate for 3 weeks first", "Not with instability."]], "ESC AF guideline 2024"],
  ["stemi", "Chest pain for 1 hour with ST elevation in II, III, aVF; the cath lab is 40 minutes away.", "Aspirin, P2Y12 inhibitor, primary PCI transfer", "PCI within 120 minutes of diagnosis is preferred to thrombolysis.", [["Aspirin, troponin, transfer when positive", "Don't wait for troponin with ST elevation."], ["Aspirin, nitrate, discharge with review", "This is a STEMI."], ["Aspirin, thrombolysis, no transfer planned", "PCI beats lysis when it can be done in time, as here."]], "ESC ACS guideline 2023"],
  ["stemi-lysis", "STEMI in a district hospital; nearest PCI is 4 hours away; pain began 2 hours ago.", "Tenecteplase in 30 minutes, then transfer", "When PCI can't be done within 120 minutes, lyse if no contraindication.", [["Transfer for PCI now, with no thrombolysis", "Too late for the heart muscle."], ["Heparin alone, then transfer tomorrow", "Doesn't open the artery."], ["IV metoprolol, then transfer for PCI", "Not the priority, and PCI is too far away."]], "ESC ACS 2023; ICMR STEMI guidelines"],
  ["acs-nstemi", "Chest pain with ST depression and a raised troponin; stable.", "Antithrombotics; early angiography", "NSTEMI: aspirin, P2Y12 inhibitor and anticoagulation, with angiography within 24 hours if high risk.", [["Thrombolysis; early angiography", "Not for NSTEMI."], ["Antithrombotics; immediate CABG", "Not first: define the anatomy first."], ["Aspirin; discharge with a stress test", "This is an ACS."]], "ESC ACS guideline 2023"],
  ["apo", "Sudden breathlessness, crackles to the apices, SpO₂ 84%, BP 180/100.", "Sit up, CPAP, IV nitrates, furosemide", "Hypertensive pulmonary oedema: nitrates lower preload and afterload.", [["Lie flat, oxygen, IV fluids, review", "Fluids worsen oedema."], ["Sit up, oxygen, IV metoprolol, review", "An IV beta-blocker can precipitate shock."], ["Sit up, oxygen, IV morphine, review", "Morphine is no longer routine, and the BP goes untreated."]], "ESC heart failure guideline 2021"],
  ["tamponade", "After chest trauma: hypotension, raised JVP, muffled heart sounds; pericardial fluid on FAST.", "Urgent pericardiocentesis or thoracotomy", "Beck's triad: relieve the tamponade, with fluids as a bridge.", [["Fluid bolus, then IV furosemide", "Diuretics worsen it."], ["Left-sided chest drain insertion", "For pneumothorax or haemothorax."], ["CT chest first, then a procedure if confirmed", "Don't delay."]], "ATLS 10th edition"],
  ["massive-pe", "Collapse with SpO₂ 82%, BP 70/40 and a dilated right ventricle on echo; suspected PE.", "Systemic thrombolysis with alteplase", "High-risk PE with shock: reperfuse now.", [["LMWH, then review at 24 hours", "For non-shocked PE."], ["IVC filter before anticoagulation", "Only if anticoagulation is contraindicated."], ["IV furosemide for the RV strain", "Lowers preload and worsens RV failure."]], "ESC PE guideline 2019"],
  ["aortic-dissection", "Tearing chest pain to the back, a BP difference between arms of 30 mmHg.", "IV labetalol first, then CT angiogram", "Reduce shear stress first (HR under 60, systolic 100–120); type A needs surgery.", [["Thrombolysis first, then CT angiogram", "Fatal in dissection."], ["IV nitroprusside first, then CT angiogram", "A vasodilator before a beta-blocker causes reflex tachycardia."], ["Analgesia alone, then outpatient CT", "Lethal."]], "ESC aortic disease guideline 2024"],
  ["hypertensive-emergency", "BP 220/130 with confusion and papilloedema.", "IV labetalol, MAP down ≤ 25% in an hour", "Lower BP in a controlled way to protect perfusion (nicardipine is an alternative).", [["Sublingual nifedipine, BP normal in minutes", "Unpredictable falls cause stroke."], ["IV nitroprusside, BP normal in minutes", "Normalising within minutes is dangerous."], ["Oral amlodipine, review in a week", "This is an emergency."]], "ESC/ESH hypertension guideline 2023"],
  ["asthma-severe", "Acute severe asthma: can't complete sentences, PEFR 40%, HR 125.", "Oxygen, salbutamol–ipratropium nebs, steroids", "Bronchodilators and steroids early; magnesium if not improving.", [["Oxygen, chest X-ray first, then nebulisers", "Treat first; X-ray only if a complication is suspected."], ["Oxygen, sedation for the distress", "Sedation can stop breathing."], ["Oxygen, IV antibiotics, then review", "Only if infection; bronchodilators are what's needed."]], "GINA 2024; BTS/SIGN"],
  ["asthma-lifethreat", "Asthma with a silent chest, SpO₂ 89% and exhaustion despite nebulisers.", "IV magnesium 2 g and ICU referral", "Life-threatening features need escalation and possible intubation.", [["Oral prednisolone and ward review", "Not enough for a silent chest."], ["IV midazolam and ward review", "Sedation can stop breathing."], ["Saline nebuliser and home with review", "Life-threatening: he can't leave."]], "BTS/SIGN asthma guideline"],
  ["copd-exac", "COPD exacerbation: pH 7.29, PaCO₂ 65 mmHg after an hour of nebulisers and controlled oxygen.", "Non-invasive ventilation (BiPAP)", "Hypercapnic acidosis persisting after medical therapy: NIV.", [["15 L/min oxygen by reservoir mask", "Worsens CO₂ retention."], ["Immediate intubation and ventilation", "Try NIV first unless contraindicated."], ["Oral prednisolone and discharge", "Acidotic: he stays."]], "GOLD 2024; BTS NIV guideline"],
  ["airway-obstruction", "A choking adult can't speak or cough effectively and is still conscious.", "5 back blows, then 5 abdominal thrusts", "Severe airway obstruction in a conscious adult: repeat the cycle.", [["5 chest compressions, then a finger sweep", "Compressions are for when she becomes unresponsive; a blind sweep can push it deeper."], ["Sips of water, then a blind finger sweep", "Water is dangerous, and a blind sweep can push it deeper."], ["Encourage coughing, then reassess later", "Only for a cough that's still effective."]], "Resuscitation Council UK 2021"],
  ["choking-infant", "A 7-month-old choking on a peanut, conscious, with an ineffective cough.", "5 back blows, then 5 chest thrusts", "Repeat the cycle. Abdominal thrusts aren't used in infants.", [["5 back blows, then 5 abdominal thrusts", "Abdominal thrusts can injure an infant's liver."], ["Blind finger sweep, then 5 back blows", "Can impact the object."], ["Upside-down shake, then 5 chest thrusts", "Not recommended."]], "Resuscitation Council UK PLS 2021"],
  ["paeds-arrest", "A child in cardiac arrest; you're alone.", "5 rescue breaths, then 15:2 CPR", "Paediatric arrests are mostly respiratory; breaths first.", [["Compressions only, with no breaths", "The problem is usually hypoxia, so breaths are essential."], ["AED shock first, then 15:2 CPR", "Most are non-shockable; breaths come first."], ["30-second pulse check, then 15:2 CPR", "Too long: no more than 10 seconds."]], "ERC Paediatric Life Support 2021"],
  ["neonatal-resus", "A newborn is floppy and not breathing at 30 seconds after drying.", "Open the airway; start mask ventilation", "Ventilation is the key to newborn resuscitation (ERC starts with 5 inflation breaths).", [["Start chest compressions at 3:1 with breaths", "Only if HR < 60 after effective ventilation."], ["Give IV adrenaline via the umbilical vein", "Only if the heart rate stays low after ventilation and compressions."], ["Deep suction of the mouth and the trachea", "Not routine: it can cause bradycardia and delays breaths."]], "NRP 8th edition; ERC NLS 2021"],
  ["burns-fluid", "A 70 kg adult with 30% partial and full-thickness burns, 2 hours ago.", "Parkland 8.4 L, half within 8 h of the burn", "4 mL × 70 × 30 = 8.4 L in 24 h. Count from the time of the burn, not arrival, and titrate to urine output.", [["Parkland 8.4 L, half within 8 h of arrival", "The clock starts at the burn, not arrival."], ["Parkland 16.8 L, half within 8 h of the burn", "Twice the Parkland figure: risks fluid creep and compartment syndrome."], ["Parkland 2.1 L, half within 8 h of the burn", "A quarter of the Parkland figure: under-resuscitates."]], "ATLS; ANZBA EMSB"],
  ["trauma-primary", "A motorcyclist after a crash: noisy breathing, BP 90/60, GCS 12.", "Airway first, with C-spine protection", "ABCDE: treat in the order that kills first.", [["CT head first, with C-spine protection", "Airway first."], ["Splint fractures first, then the airway", "Later."], ["Blood glucose first, then the airway", "Airway and breathing first."]], "ATLS 10th edition"],
  ["haemorrhage", "Trauma with HR 130, BP 80/50 and a pelvic fracture.", "Pelvic binder, TXA and blood products", "Haemorrhagic shock: stop the bleeding, TXA within 3 hours, permissive hypotension, balanced transfusion.", [["Four litres of crystalloid, then review", "Dilutes clotting."], ["CT pelvis first, then blood products", "Unstable: treat first."], ["Noradrenaline first, then crystalloid", "Treat the bleed, not the number."]], "ATLS 10th edition; CRASH-2"],
  ["head-injury", "Head injury, GCS 8, one pupil dilated.", "Intubate, hypertonic saline, urgent CT", "Signs of herniation: secure the airway, avoid hypoxia and hypotension, osmotherapy, CT and neurosurgery.", [["Lumbar puncture, then urgent CT", "Contraindicated."], ["Hypotonic fluids, then urgent CT", "Worsen oedema."], ["Observe 4 hours, then repeat GCS", "GCS 8 needs airway control."]], "Brain Trauma Foundation; NICE head injury"],
  ["c-spine", "A conscious 30-year-old after a minor fall, no midline tenderness, no neuro signs, can rotate the neck 45°.", "Clear clinically; no imaging needed", "Low-risk patients who can rotate 45° don't need imaging (Canadian C-spine rule).", [["CT cervical spine before clearance", "Unnecessary radiation."], ["Rigid collar for 6 weeks", "Not needed."], ["MRI cervical spine today", "Not indicated."]], "Canadian C-spine rule; NICE"],
  ["meningitis", "Fever, neck stiffness and a purpuric rash in an 18-year-old.", "IV ceftriaxone now, then investigate", "Suspected meningococcal disease: take blood cultures, give steroids, and don't delay antibiotics.", [["CT, then LP, then IV ceftriaxone", "Antibiotics first."], ["LP first, then IV ceftriaxone", "Delays treatment, and a purpuric rash is itself a reason not to wait."], ["Oral amoxicillin now, then review", "Too little."]], "NICE meningitis guideline 2024"],
  ["hypoglycaemia", "A diabetic is drowsy, sweating, with glucose 40 mg/dL and can't swallow.", "IV 10% dextrose, or IM glucagon", "Unconscious hypoglycaemia: IV glucose or, with no access, glucagon.", [["Oral glucose gel, or sweet tea", "Risk of aspiration."], ["Send a lab glucose, then treat", "Treat now."], ["SC octreotide, or observe", "Octreotide is for sulfonylurea overdose, and she can't wait."]], "JBDS hypoglycaemia guideline"],
  ["hhs", "An elderly diabetic, confused, glucose 900 mg/dL, osmolality 360, no ketoacidosis.", "IV 0.9% saline; low-dose insulin later", "HHS: fluids are the main treatment; start insulin when glucose stops falling with fluids, to avoid rapid osmolality shifts.", [["IV insulin bolus; saline only later", "Causes rapid falls and oedema."], ["IV 0.45% saline; insulin bolus now", "Osmolality falls too fast."], ["IV bicarbonate; low-dose insulin later", "Not indicated: there's no ketoacidosis."]], "JBDS HHS guideline"],
  ["adrenal-crisis", "On long-term steroids, vomiting, BP 70/40, sodium 126, potassium 5.8.", "IV hydrocortisone 100 mg with saline", "Adrenal crisis: steroid and fluids immediately.", [["Oral fludrocortisone 100 mcg with saline", "Too slow, and she's vomiting."], ["IV dexamethasone 0.5 mg with saline", "Too small a dose, with no mineralocorticoid effect."], ["Await a cortisol result, with saline", "Give hydrocortisone now."]], "Society for Endocrinology emergency guidance"],
  ["thyroid-storm", "Fever 40°C, HR 160 in AF, agitation and a goitre.", "Propranolol, PTU, iodine later, steroid", "Block the effects, the synthesis and then the release; iodine an hour after PTU.", [["Iodine first, then PTU and propranolol", "Iodine before a thionamide can fuel more hormone."], ["Propranolol, PTU, aspirin for the fever", "Aspirin displaces T4 from its binding protein."], ["Carbimazole alone, then review at 24 hours", "Too slow and too little for a storm."]], "ATA thyroid storm guidance"],
  ["myxoedema", "Hypothermic, confused, bradycardic elderly woman with TSH 90.", "IV hydrocortisone, then IV levothyroxine", "Steroid first in case of adrenal insufficiency.", [["Oral levothyroxine, then hydrocortisone", "Too slow, and the steroid must come first."], ["IV levothyroxine, active rapid rewarming", "Rapid rewarming causes collapse."], ["IV sedation, then IV levothyroxine", "Dangerous: she's already obtunded."]], "ATA hypothyroidism guideline"],
  ["hyponatraemia", "Sodium 112 mmol/L with seizures.", "3% saline 150 mL, rise ≤ 10 in 24 h", "Severe symptomatic hyponatraemia: 150 mL over 20 minutes, repeated until symptoms settle, avoiding over-rapid correction.", [["3% saline 150 mL, to 135 in 24 h", "Risks osmotic demyelination."], ["0.45% saline 1 L, rise ≤ 10 in 24 h", "Hypotonic: it won't help."], ["Fluid restriction, rise ≤ 10 in 24 h", "Too slow with seizures."]], "European hyponatraemia guideline 2014"],
  ["eclampsia", "A woman at 36 weeks fits; BP 170/110 with proteinuria.", "IV magnesium sulfate, then plan delivery", "Magnesium (loading dose 4 g) prevents and treats eclamptic seizures; control BP; delivery is the cure.", [["IV diazepam, then plan delivery", "Magnesium is superior."], ["IV phenytoin, then plan delivery", "Inferior to magnesium."], ["Oral nifedipine, then expectant care", "No seizure treatment, and delivery is the cure."]], "WHO; FOGSI; NICE hypertension in pregnancy"],
  ["shoulder-dystocia", "The head is delivered but the shoulders don't follow.", "McRoberts with suprapubic pressure", "Call for help. First-line manoeuvres (HELPERR): McRoberts and suprapubic pressure.", [["Fundal pressure with firm traction", "Worsens impaction."], ["Immediate caesarean section", "Not first line."], ["Firm downward traction on the head", "Brachial plexus injury."]], "RCOG Green-top guideline 42"],
  ["cord-prolapse", "The membranes rupture and the cord is felt in the vagina.", "Lift the presenting part; urgent delivery", "Prevent cord compression until delivery, in the knee–chest position.", [["Replace the cord; knee–chest; await labour", "Pushing the cord back isn't recommended."], ["Keep upright; wait for full dilatation", "Fetal hypoxia."], ["Handle the cord often; await labour", "Causes spasm."]], "RCOG Green-top guideline 50"],
  ["ectopic-ruptured", "Positive pregnancy test, abdominal pain, BP 80/50 and free fluid on FAST.", "Resuscitate and go to theatre", "Ruptured ectopic with shock: laparoscopy or laparotomy.", [["IM methotrexate and repeat hCG", "For stable, unruptured ectopics."], ["Repeat hCG in 48 hours", "Unstable."], ["Admit for expectant care", "Unstable."]], "RCOG; NICE ectopic pregnancy"],
  ["dehydration-child", "A 1-year-old with diarrhoea, lethargy, sunken eyes, unable to drink, skin pinch goes back very slowly.", "IV Ringer's lactate 100 mL/kg (Plan C)", "Severe dehydration. WHO Plan C: 30 mL/kg then 70 mL/kg — over 1 h then 5 h under 12 months; over 30 minutes then 2.5 h from 12 months.", [["ORS 75 mL/kg by NG tube over 4 hours (Plan B)", "For some dehydration; severe dehydration needs IV fluids."], ["ORS and zinc at home (Plan A)", "For no dehydration."], ["Loperamide with ORS at home", "Antidiarrhoeal drugs aren't for children."]], "WHO IMCI; WHO diarrhoea guidelines"],
  ["febrile-seizure", "A 2-year-old had a 3-minute generalised seizure with fever and is now waking.", "Treat the cause; no anticonvulsant", "A simple febrile seizure needs no long-term treatment; reassure the family.", [["Start regular valproate; outpatient EEG", "Not for simple febrile seizures."], ["Urgent MRI brain; start levetiracetam", "Not needed."], ["Lumbar puncture for all; start aciclovir", "Only if meningitis or encephalitis is suspected."]], "NICE febrile illness; AAP"],
  ["sam-child", "A 2-year-old with MUAC 10.8 cm, oedema and poor appetite.", "Admit; antibiotics, warmth; start F-75", "Complicated SAM needs inpatient care (WHO 10 steps): treat hypoglycaemia, hypothermia and infection, then F-75.", [["Send home; RUTF with a weekly clinic review", "For uncomplicated SAM."], ["Admit; rapid IV fluids; start F-100", "Rapid fluids risk heart failure; start with F-75."], ["Admit; oral iron now; start F-100", "Delay iron; start with F-75."]], "WHO SAM guidelines; IAP"],
  ["sepsis-child", "A 4-year-old with fever, mottled skin, CRT 4 s, HR 170 and lethargy.", "IV access, 10–20 mL/kg bolus, antibiotics, reassess", "Paediatric septic shock: antibiotics within the hour, balanced crystalloid in careful boluses, reassessing after each.", [["IV access, 60 mL/kg without pauses, antibiotics", "Reassess after each bolus: fluid overload harms."], ["IV access, cultures, antibiotics when results are back", "Antibiotics within the hour."], ["Oral antibiotics, ORS and review tomorrow", "This is shock."]], "Surviving Sepsis Campaign Paediatric 2020"],
  ["anaphylaxis-refractory", "Anaphylaxis still severe after two doses of IM adrenaline.", "IV adrenaline infusion plus fluids", "Refractory anaphylaxis: adrenaline infusion with expert help.", [["IV chlorphenamine plus fluids", "Doesn't help the shock or the airway."], ["IV hydrocortisone plus fluids", "Too slow."], ["IM adrenaline every 5 minutes, no infusion", "Once two doses have failed, an infusion is needed: IM alone isn't enough."]], "Resuscitation Council UK 2021"],
  ["upper-gi-bleed", "Haematemesis in cirrhosis; HR 120, BP 90/60.", "Terlipressin, antibiotics, early endoscopy", "Variceal bleed: resuscitate, vasoactive drug, antibiotics, and endoscopic banding within 12 hours.", [["Large-volume saline, endoscopy next week", "Raising the portal pressure worsens bleeding, and endoscopy is within 12 hours."], ["IV propranolol, antibiotics, early endoscopy", "Not in active bleeding with shock."], ["Omeprazole alone, endoscopy next week", "Doesn't treat varices, and endoscopy is within 12 hours."]], "Baveno VII; NICE"],
  ["acute-abdomen", "Sudden severe epigastric pain, rigid abdomen and free air under the diaphragm.", "NBM, fluids, antibiotics, urgent laparotomy", "Peritonitis from a perforated ulcer needs surgery.", [["NBM, fluids, antibiotics, barium meal", "Barium is contraindicated in perforation."], ["IV PPI, then discharge with review", "Perforation needs surgery."], ["NBM, fluids, observe for 24 hours", "Sepsis risk."]], "WSES perforated peptic ulcer guideline"],
  ["testicular-torsion", "A 15-year-old with sudden severe testicular pain, a high-riding testis and absent cremasteric reflex.", "Urgent scrotal exploration", "Torsion: theatre within 6 hours saves the testis. Don't wait for an ultrasound.", [["Morning scrotal ultrasound", "Too late."], ["Antibiotics for epididymitis", "Missed torsion."], ["Analgesia and discharge", "The testis is lost."]], "EAU paediatric urology; BAUS"],
  ["compartment", "After a tibial fracture: pain out of proportion and pain on passive stretch of the toes.", "Release dressings; urgent fasciotomy", "Compartment syndrome: release within hours.", [["Elevate high; review in 4 hours", "Reduces perfusion, and it delays fasciotomy."], ["More opioids; review in 4 hours", "Delays fasciotomy."], ["Recheck pulses; fasciotomy if absent", "Absent pulses are a late sign."]], "BOAST compartment syndrome"],
  ["hyperthermia", "A labourer collapses in the heat; core temperature 41.5°C and confused.", "Cold-water immersion with fluids", "Heat stroke: cool first, fast.", [["IV paracetamol with fluids", "Doesn't work in heat stroke."], ["IV dantrolene with fluids", "Not effective in heat stroke."], ["Await blood tests, with fluids", "Cool first."]], "NDMA heat-wave guidelines; Wilderness Medical Society"],
  ["hypothermia", "Found outdoors in winter: core 28°C, VF on the monitor.", "CPR, up to 3 shocks, no drugs until 30°C", "Hypothermic arrest: modified ALS with active rewarming.", [["CPR, full ALS drugs and shocks every 3 minutes", "Drugs are withheld below 30°C, and shocks are limited to 3."], ["Stop CPR: cold, rigid and so dead", "Not dead until warm and dead."], ["CPR with passive rewarming alone", "Needs active rewarming."]], "ERC 2021 special circumstances"],
  ["drowning", "A child pulled from a pond, not breathing.", "Airway, then 5 rescue breaths, then CPR", "Drowning is hypoxic arrest; breaths first.", [["Abdominal thrusts to drain water, then CPR", "Not recommended."], ["Compressions only, with no breaths", "Oxygen first."], ["Recovery position, await the ambulance", "Start now."]], "ERC 2021 drowning"],

  /* Children */
  ["nrp-hr", "A term newborn has a heart rate of 50/min despite 30 seconds of effective positive-pressure ventilation.", "Compressions 3:1 with 100% oxygen", "Heart rate under 60 after effective ventilation: secure the airway, then 3 compressions to 1 breath.", [["Compressions 15:2 with 21% oxygen", "The older-child ratio on room air: newborns need 3:1 with 100% oxygen."], ["IV adrenaline, before any compressions", "Only if heart rate stays under 60 after compressions with ventilation."], ["Ventilation alone for 2 minutes more", "Already effective and still under 60: compressions are due."]], "NRP 8th edition (AAP/AHA)"],
  ["pals-brady", "A 2-year-old with HR 45 and poor perfusion after hypoxia, despite good oxygenation and ventilation.", "CPR, then IV adrenaline 0.01 mg/kg", "Heart rate under 60 with poor perfusion despite ventilation is treated as impending arrest.", [["IV adenosine 0.1 mg/kg, then review", "For SVT; it slows the heart further."], ["IV atropine alone, with no compressions", "Atropine is for vagal or primary AV block; CPR comes first here."], ["Transcutaneous pacing, then review", "Not first line for hypoxic bradycardia."]], "AHA PALS 2020"],
  ["pals-svt", "A 3-year-old with a narrow regular tachycardia at 240/min, with palpable pulses and good perfusion.", "Vagal manoeuvres, then adenosine 0.1 mg/kg", "Stable SVT: ice to the face or a modified Valsalva, then a rapid adenosine bolus.", [["Vagal manoeuvres, then verapamil 0.1 mg/kg", "Verapamil risks collapse in small children."], ["Synchronised shock 1 J/kg, then adenosine", "Only if unstable."], ["Eyeball pressure, then adenosine 0.1 mg/kg", "Eyeball pressure can injure the eye."]], "AHA PALS 2020"],
  ["paeds-status", "A 6-year-old is still fitting 10 minutes after two doses of IV lorazepam.", "IV levetiracetam or fosphenytoin load", "Established status: second-line, and these are similar in effect (ESETT).", [["A third dose of IV lorazepam", "More than two benzodiazepine doses adds respiratory depression without benefit."], ["Thiopentone general anaesthesia first", "Third line, for refractory status."], ["Oral carbamazepine by NG tube", "Too slow, and not for status."]], "AES status epilepticus guideline 2016; ESETT trial 2019"],
  ["croup", "A 2-year-old has a barking cough, stridor at rest and mild retractions, but is drinking.", "Dexamethasone with nebulised adrenaline", "Steroids shorten the illness; nebulised adrenaline buys time with stridor at rest. Keep the child calm.", [["Salbutamol nebuliser with oral amoxicillin", "The obstruction is upper-airway and viral."], ["Ceftriaxone with salbutamol nebuliser", "The obstruction is upper-airway and viral."], ["Mist tent with oral antihistamine", "Neither works."]], "Nelson Textbook of Pediatrics; Cochrane review of glucocorticoids for croup"],
  ["epiglottitis", "An unvaccinated 4-year-old sits forward drooling, toxic and febrile, with a muffled voice and soft stridor.", "Keep upright; senior airway team; ceftriaxone", "Don't upset the child: secure the airway in theatre with ENT and anaesthesia, then cannulate and give antibiotics.", [["Lie flat; throat exam with spatula; ceftriaxone", "Lying flat or a spatula can cause complete obstruction."], ["Lie flat; lateral neck X-ray; ceftriaxone", "Lying flat, or leaving for X-ray, can cause complete obstruction."], ["Keep upright; oral dexamethasone; home", "This is a life-threatening airway: she can't go home."]], "Nelson Textbook of Pediatrics; APLS"],
  ["bronchiolitis", "A 4-month-old in RSV season with cough, wheeze and crackles, SpO₂ 88% and poor feeding.", "Oxygen and NG feeds, with no drugs", "Bronchiolitis is supportive: oxygen and fluids; bronchodilators, steroids and antibiotics don't help.", [["Oxygen and regular salbutamol nebulisers", "Not recommended: no lasting benefit in bronchiolitis."], ["Oxygen and oral prednisolone", "Not recommended: steroids don't help."], ["Oxygen and IV co-amoxiclav", "Viral: only if a bacterial infection is suspected."]], "NICE bronchiolitis guideline; AAP 2014"],
  ["tet-spell", "A 9-month-old with tetralogy of Fallot turns deeply blue and limp after crying.", "Knee–chest, oxygen, IV morphine", "Raise systemic resistance and relax the outflow tract; if it persists, give fluid, phenylephrine or propranolol.", [["Knee–chest, oxygen, IV dobutamine", "An inotrope worsens the outflow obstruction."], ["Sit up, oxygen, IV furosemide", "Lowers preload and worsens the spell."], ["Lay flat, oxygen, IV digoxin", "Inotropic, and doesn't raise systemic resistance."]], "Nelson Textbook of Pediatrics; Park's Pediatric Cardiology"],

  /* Women and babies */
  ["pph-second", "PPH continues with a soft uterus despite massage and an oxytocin infusion. She isn't asthmatic.", "TXA, carboprost, then balloon tamponade", "Think of the 4 Ts (tone, trauma, tissue, thrombin): add tranexamic acid and more uterotonics, then a balloon if still bleeding.", [["More massage alone, review in 30 minutes", "She's still bleeding: keep escalating."], ["Immediate hysterectomy, no more drugs", "Last resort, after drugs and conservative measures."], ["FFP first, uterotonics once clotting is back", "Atony must be treated now; don't wait for results."]], "RCOG Green-top guideline 52; WHO PPH recommendations; WOMAN trial"],
  ["maternal-arrest", "Cardiac arrest at 36 weeks; CPR has started; the fundus is above the umbilicus.", "Left uterine displacement; hysterotomy by 5 min", "Displacing the uterus relieves aortocaval compression; if no ROSC, resuscitative hysterotomy by 4–5 minutes helps mother and baby.", [["Left uterine displacement; hysterotomy by 30 min", "Far too late: aim for 4–5 minutes."], ["Supine CPR; hysterotomy only after ROSC", "Supine CPR compresses the aorta and cava, and delivery is part of the resuscitation."], ["Supine CPR; withhold shocks until delivery", "Shocks are given as usual."]], "AHA ACLS 2020 (arrest in pregnancy); RCOG maternal collapse guideline"],
  ["mag-toxicity", "On magnesium sulfate for eclampsia: knee jerks are gone, RR 8/min and urine is scanty.", "Stop magnesium; IV calcium gluconate 1 g", "Magnesium toxicity: calcium antagonises it (10 mL of 10%), with oxygen and ventilation as needed.", [["Halve magnesium; IV calcium gluconate 1 g", "Respiratory depression needs it stopped, not halved."], ["Stop magnesium; IV naloxone 400 mcg", "For opioids."], ["Keep magnesium; IV furosemide 40 mg", "Toxicity needs it stopped, and furosemide is too slow."]], "WHO; NICE hypertension in pregnancy"],
  ["severe-htn-pregnancy", "At 34 weeks, BP stays 170/115 on repeat measurement, with a headache.", "IV labetalol, within the hour", "Severe hypertension in pregnancy: labetalol, hydralazine or oral nifedipine, to prevent stroke.", [["IV enalaprilat, within the hour", "ACE inhibitors harm the fetus."], ["Oral losartan, within the hour", "ARBs harm the fetus."], ["Oral methyldopa, review tomorrow", "Too slow for a severe rise."]], "ACOG; NICE hypertension in pregnancy"],
  ["uterine-inversion", "During controlled cord traction: sudden shock, a mass at the vulva and no fundus palpable.", "Immediate manual uterine replacement", "Uterine inversion: replace at once (Johnson's manoeuvre); uterotonics only after it's back.", [["Oxytocin bolus, then replacement", "Contracting the uterus makes replacing it harder."], ["More cord traction, then replacement", "Traction made this and adds to it."], ["Laparotomy before any replacement", "Only if manual and hydrostatic replacement fail."]], "WHO Managing Complications in Pregnancy and Childbirth; Williams Obstetrics"],
  ["abruption", "At 34 weeks: sudden painful dark bleeding, a woody-hard uterus and fetal heart rate 90/min.", "Resuscitate, then caesarean now", "Abruption with fetal distress: deliver fast, and watch for DIC.", [["Tocolysis, then observe for 48 hours", "Contraindicated with this bleeding and fetal distress."], ["Steroids, then deliver in 48 hours", "The fetus doesn't have 48 hours."], ["Digital vaginal exam, then observe", "Observation loses the baby; never examine digitally before excluding praevia."]], "RCOG antepartum haemorrhage guideline"],

  /* Brain and nerves */
  ["sah", "Sudden worst-ever headache 2 hours ago, with neck stiffness; GCS 15.", "Urgent non-contrast CT head", "Thunderclap headache: CT within 6 hours is highly sensitive; CT angiography or LP next if needed.", [["Lumbar puncture, then CT head", "CT first; LP is only if CT is negative, and later."], ["Sumatriptan, then review", "Treats migraine and misses a bleed that may re-bleed."], ["Outpatient MRI brain", "Too slow."]], "AHA/ASA aneurysmal subarachnoid haemorrhage guideline 2023"],
  ["gbs", "Ascending weakness and areflexia a week after diarrhoea; he can't walk and vital capacity is falling.", "IV immunoglobulin, with FVC monitoring", "Guillain–Barré: IVIg or plasma exchange; watch breathing and autonomic function, and don't wait for hypoxia.", [["IV methylprednisolone, with FVC monitoring", "Steroids don't help Guillain–Barré."], ["Oral pyridostigmine, with FVC monitoring", "For myasthenia."], ["IV aciclovir, with FVC monitoring", "For herpes encephalitis."]], "EAN/PNS Guillain–Barré guideline 2023"],
  ["myasthenic-crisis", "Known myasthenia with a chest infection: weak neck, poor swallow, vital capacity 15 mL/kg.", "IVIg with ventilatory support", "Myasthenic crisis: secure breathing early, with IVIg or plasma exchange, and treat the trigger.", [["Extra pyridostigmine with ward review", "Adds secretions, and can't rescue failing breathing."], ["IV gentamicin with ventilatory support", "Aminoglycosides worsen myasthenia."], ["IV magnesium with ventilatory support", "Magnesium worsens neuromuscular block."]], "International consensus guidance for myasthenia gravis (2016, updated 2020)"],
  ["encephalitis", "Fever, confusion, odd behaviour and a temporal-lobe seizure.", "IV aciclovir now, then MRI and LP", "Suspected HSV encephalitis: treatment within hours saves function, so don't wait for tests.", [["Await HSV PCR, then IV aciclovir", "Delay worsens the outcome."], ["Oral aciclovir now, then MRI and LP", "Too little reaches the brain."], ["IV ceftriaxone alone, then MRI", "Doesn't treat HSV."]], "Association of British Neurologists / BIA encephalitis guideline 2012"],
  ["cord-compression", "Known prostate cancer: back pain, leg weakness, a sensory level and urinary retention.", "Dexamethasone and whole-spine MRI now", "Malignant cord compression: walking at presentation decides walking afterwards, so image the same day, then surgery or radiotherapy.", [["Analgesia and routine outpatient MRI", "Too slow: paralysis can become permanent."], ["Lumbar puncture, then MRI tomorrow", "LP risks worsening compression, and it's too slow."], ["Spine X-ray, then physiotherapy", "X-ray misses it, and it's too slow."]], "NICE spinal metastases and metastatic spinal cord compression guideline"],
  ["lvo", "Left hemiplegia and gaze palsy 3 hours ago; CT shows no bleed and CT angiography shows a right M1 occlusion.", "Thrombolysis and mechanical thrombectomy", "Large-vessel occlusion: IV lysis if eligible, without holding back from thrombectomy.", [["Aspirin and ward admission", "Misses both reperfusion treatments."], ["Heparin infusion and ward admission", "No benefit, and it can bleed."], ["Thrombolysis and decompressive craniectomy", "Craniectomy is for later malignant oedema; the occlusion needs opening."]], "AHA/ASA acute stroke guideline 2019"],

  /* Shock */
  ["septic-vasopressor", "Septic shock after 30 mL/kg of crystalloid: MAP 55 and lactate 5.", "Noradrenaline, target MAP ≥ 65", "First-line vasopressor, peripheral if need be, to avoid delay.", [["Dopamine, target MAP ≥ 90", "More arrhythmia than noradrenaline, and the target's too high."], ["Hydrocortisone alone, no vasopressor", "Only an add-on when vasopressor doses are rising."], ["Three more litres, no vasopressor", "More fluid without a response harms."]], "Surviving Sepsis Campaign 2021"],
  ["neurogenic-shock", "Cervical spine injury: BP 78/40, HR 48, warm pink legs and no bleeding found.", "Cautious fluids, vasopressor, atropine", "Loss of sympathetic tone gives low BP without tachycardia; exclude bleeding first.", [["Massive transfusion, then laparotomy", "No bleed has been found; warm skin with bradycardia points to neurogenic."], ["IV furosemide, then dobutamine", "She's vasodilated, not overloaded."], ["High-dose methylprednisolone alone", "Not recommended, and it doesn't treat shock."]], "ATLS 10th edition"],
  ["massive-transfusion", "Major trauma: 6 units of red cells given, still bleeding, and ionised calcium is low.", "Red cells, plasma, platelets 1:1:1 with calcium", "Balanced transfusion avoids dilutional coagulopathy; citrate lowers calcium, so replace it.", [["Red cells alone until clotting results are back", "Dilutes clotting factors and platelets further."], ["Crystalloid 3:1 with red cells, no calcium", "Dilutes clotting and worsens the low calcium."], ["Albumin and red cells, with no plasma", "Doesn't replace the clotting factors."]], "ATLS 10th edition; PROPPR 2015"],
  ["cardiogenic-shock", "Anterior STEMI with BP 78/50, cold skin, lung crackles and lactate 6.", "Noradrenaline, then culprit-vessel PCI", "Cardiogenic shock: support the pressure and open the culprit vessel fast.", [["30 mL/kg fluid, then culprit-vessel PCI", "The lungs are already wet."], ["IV metoprolol, then culprit-vessel PCI", "A beta-blocker in shock can kill."], ["IV nitrates, then elective angiography", "Lowers the BP further, and it can't wait."]], "ESC ACS guideline 2023; SHOCK and CULPRIT-SHOCK trials"],

  /* Chest pain and heart */
  ["rv-infarct", "Inferior STEMI: BP 85/50, raised JVP, clear lungs and ST elevation in V4R.", "Cautious fluids, stop nitrates, PCI", "Right ventricular infarct is preload dependent; avoid anything that drops preload.", [["IV nitrates and furosemide, then PCI", "Both drop preload and worsen the hypotension."], ["IV morphine, nitrates, PCI", "Both drop preload and worsen the hypotension."], ["IV metoprolol, nitrates, PCI", "Worsen RV failure and hypotension."]], "ESC ACS guideline 2023"],

  /* Trauma */
  ["massive-haemothorax", "Penetrating chest wound, dull to percussion, BP 80/50; the chest drain yields 1,600 mL of blood at once.", "Blood products and urgent thoracotomy", "An initial output over 1,500 mL (or ongoing losses) means surgical bleeding.", [["Blood products, clamp drain, observe 6 hours", "Hides, but doesn't stop, the bleeding."], ["Blood products, second drain, CT chest", "He's unstable: another drain won't stop surgical bleeding."], ["Needle decompression and observation", "For tension pneumothorax."]], "ATLS 10th edition"],
  ["fast-positive", "Blunt abdominal injury: HR 130, BP 80/50 despite blood; FAST shows free fluid.", "Laparotomy now, with blood products", "An unstable patient with a positive FAST goes straight to theatre.", [["CT abdomen, then laparotomy if needed", "CT is only for stable patients."], ["Repeat FAST in 30 minutes, with blood", "It's already positive, and he's unstable."], ["Peritoneal lavage, then CT abdomen", "FAST has already answered this."]], "ATLS 10th edition"],
  ["open-fracture", "An open tibial fracture with bone visible, contaminated with soil.", "IV antibiotics now; theatre for debridement", "Antibiotics within an hour, then a splint, tetanus cover and surgical debridement.", [["Wash in ED, suture; oral antibiotics", "Closing a contaminated wound invites deep infection."], ["Plaster cast; fracture clinic next week", "Far too late for an open fracture."], ["Wound swab first; antibiotics if positive", "Antibiotics can't wait for a swab."]], "BOAST open fractures; NICE fractures (complex)"],

  /* Airway and breathing */
  ["cico", "Failed intubation, SpO₂ 70% and falling; mask and supraglottic airway have both failed.", "Scalpel–bougie cricothyroidotomy", "Can't intubate, can't oxygenate: front-of-neck access now.", [["A fifth laryngoscopy attempt", "Repeated attempts cause swelling and waste time."], ["A third supraglottic airway", "Has already failed; time is running out."], ["Wait for the muscle relaxant to wear off", "Hypoxic arrest comes first."]], "Difficult Airway Society guidelines 2015"],
  ["massive-haemoptysis", "Known TB, coughing up fresh blood, about 300 mL so far, from the left lung on CT.", "Left side down; airway; embolisation", "Keep the bleeding lung down to protect the good lung; intubate if needed; bronchial artery embolisation.", [["Right side down; airway; embolisation", "Blood runs into the good lung."], ["Sit up; salbutamol nebs; CT tomorrow", "Doesn't protect the good lung, and CT tomorrow is too late."], ["Sedate; cough suppressant; CT tomorrow", "Blood stays in the airway; this can drown him."]], "Murray & Nadel's Textbook of Respiratory Medicine"],
  ["ards-vent", "Intubated with pneumonia: bilateral opacities, P/F 120, tidal volume 10 mL/kg, plateau pressure 34.", "Tidal 6 mL/kg; plateau ≤ 30; prone", "Lung-protective ventilation; prone for over 12 hours a day if P/F is under 150.", [["Tidal 10 mL/kg; plateau ≤ 40; supine", "Higher volumes and pressures injure the lung."], ["Tidal 12 mL/kg; PEEP 0; normal CO₂", "Higher volumes injure the lung, and PEEP 0 loses recruitment."], ["Tidal 8 mL/kg; routine oscillation", "Routine oscillatory ventilation raised mortality."]], "ARDSNet 2000; PROSEVA 2013; ATS/ESICM ventilation guideline 2017"],
  ["blocked-trach", "A tracheostomy patient has sudden breathing difficulty and the suction catheter won't pass.", "Remove the inner tube, then deflate cuff", "Blocked tube: call for help, oxygen to face and stoma; if still stuck, remove the tracheostomy and oxygenate from above.", [["Bag hard through the tube, then sedate", "Forces air against a block and causes surgical emphysema."], ["Saline nebuliser, then review in an hour", "Too slow for a blocked tube."], ["IV salbutamol, then review in an hour", "The problem is a block in the tube, not bronchospasm."]], "National Tracheostomy Safety Project"],
  ["pneumothorax-spont", "A tall 25-year-old smoker with sudden chest pain, very breathless; a large pneumothorax on X-ray; stable BP.", "Needle aspiration, then reassess", "Symptomatic primary pneumothorax: aspirate or use a small-bore drain.", [["Thoracotomy, then pleurodesis", "Surgery is for recurrent or persistent leaks."], ["Discharge, then review at 2 weeks", "Conservative care needs minimal symptoms; he's very breathless."], ["Positive-pressure ventilation first", "Can turn it into a tension pneumothorax."]], "BTS pleural disease guideline 2023"],
];
